434	+package main
435	+
436	+import (
437	+	"fmt"
438	+	"strconv"
439	+)
440	+
441	+// currencyInfo describes how a currency's minor units are written.
442	+type currencyInfo struct {
443	+	Code     string
444	+	Exponent int // number of minor-unit digits, e.g. 2 for USD
445	+}
446	+
447	+var currencies = map[string]currencyInfo{}
448	+
449	+func init() {
450	+	for _, c := range []currencyInfo{
451	+		{Code: "USD", Exponent: 2},
452	+		{Code: "EUR", Exponent: 2},
453	+		{Code: "GBP", Exponent: 2},
454	+		{Code: "CAD", Exponent: 2},
455	+		{Code: "JPY", Exponent: 0},
456	+	} {
457	+		currencies[c.Code] = c
458	+	}
459	+}
460	+
461	+// FormatAmount renders an amount in minor units as a decimal string for
462	+// display, e.g. 12345 USD -> "123.45" and 500 JPY -> "500".
463	+func FormatAmount(minor int64, currency string) string {
464	+	info, ok := currencies[currency]
465	+	if !ok || info.Exponent == 0 {
466	+		return strconv.FormatInt(minor, 10)
467	+	}
468	+	scale := int64(1)
469	+	for i := 0; i < info.Exponent; i++ {
470	+		scale *= 10
471	+	}
472	+	return fmt.Sprintf("%d.%0*d", minor/scale, info.Exponent, minor%scale)
473	+}
