615	+// Send asks the provider to pay out p. Network errors, 429 and 5xx answers
616	+// are retried with exponential backoff; the provider deduplicates retries by
617	+// the idempotency key.
618	+func (c *PayoutClient) Send(ctx context.Context, p PayoutRequest) (PayoutResult, error) {
619	+	body, err := json.Marshal(providerPayout{
620	+		AmountMinor: int32(p.AmountCents),
621	+		Currency:    p.Currency,
622	+		Destination: p.Destination,
623	+		Reference:   p.Reference,
624	+	})
625	+	if err != nil {
626	+		return PayoutResult{}, err
627	+	}
628	+
629	+	var res PayoutResult
630	+	for attempt := 1; attempt <= c.maxAttempts; attempt++ {
631	+		if attempt > 1 {
632	+			select {
633	+			case <-time.After(c.backoff << (attempt - 2)):
634	+			case <-ctx.Done():
635	+				return PayoutResult{}, ctx.Err()
636	+			}
637	+		}
638	+		res, err := c.post(ctx, body, p.Reference)
639	+		if err == nil {
640	+			return res, nil
641	+		}
642	+		var rejected *rejectedError
643	+		if errors.As(err, &rejected) {
644	+			return PayoutResult{}, err
645	+		}
646	+		log.Printf("payout %s: attempt %d/%d: %v", p.Reference, attempt, c.maxAttempts, err)
647	+	}
648	+	return res, err
649	+}
