651	+func (c *PayoutClient) post(ctx context.Context, body []byte, idempotencyKey string) (PayoutResult, error) {
652	+	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+"/v1/payouts", bytes.NewReader(body))
653	+	if err != nil {
654	+		return PayoutResult{}, err
655	+	}
656	+	req.Header.Set("Content-Type", "application/json")
657	+	req.Header.Set("Authorization", "Bearer "+c.apiKey)
658	+	req.Header.Set("Idempotency-Key", idempotencyKey)
659	+
660	+	resp, err := c.http.Do(req)
661	+	if err != nil {
662	+		return PayoutResult{}, err
663	+	}
664	+	if resp.StatusCode == http.StatusTooManyRequests || resp.StatusCode >= 500 {
665	+		return PayoutResult{}, fmt.Errorf("payout provider: status %d", resp.StatusCode)
666	+	}
667	+	defer resp.Body.Close()
668	+
669	+	if resp.StatusCode >= 400 {
670	+		msg, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
671	+		return PayoutResult{}, &rejectedError{status: resp.StatusCode, body: string(msg)}
672	+	}
673	+	var out PayoutResult
674	+	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
675	+		return PayoutResult{}, fmt.Errorf("decode payout response: %w", err)
676	+	}
677	+	return out, nil
678	+}
