130	type payoutRequest struct {
131		AmountCents int64  `json:"amount_cents"`
132		Destination string `json:"destination"`
133	}
134	
135	func (s *Server) createPayout(w http.ResponseWriter, r *http.Request) {
136		acct := accountFrom(r.Context())
137		var req payoutRequest
138		if err := decodeJSON(r, &req); err != nil {
139			writeErr(w, http.StatusBadRequest, err.Error())
140			return
141		}
142		if req.AmountCents <= 0 || req.AmountCents > maxPayoutCents {
143			writeErr(w, http.StatusBadRequest, fmt.Sprintf("amount_cents must be between 1 and %d", maxPayoutCents))
144			return
145		}
146		if req.Destination == "" {
147			writeErr(w, http.StatusBadRequest, "destination is required")
148			return
149		}
150		if acct.BalanceCents < req.AmountCents {
151			writeStoreError(w, "payout", ErrInsufficientFunds)
152			return
153		}
154	
155		ref, err := newReference("po")
156		if err != nil {
157			writeStoreError(w, "payout reference", err)
158			return
159		}
160		e, err := s.store.Withdraw(r.Context(), acct.ID, req.AmountCents, ref)
161		if err != nil {
162			writeStoreError(w, "payout debit", err)
163			return
164		}
165	
166		res, err := s.payouts.Send(r.Context(), PayoutRequest{
167			AmountCents: req.AmountCents,
168			Currency:    acct.Currency,
169			Destination: req.Destination,
170			Reference:   ref,
171		})
172		if err != nil {
173			log.Printf("payout %s for account %d failed: %v", ref, acct.ID, err)
174			if _, rerr := s.store.Credit(r.Context(), acct.ID, req.AmountCents, "payout_reversal", ref); rerr != nil {
175				log.Printf("payout %s: reversal failed, manual fix needed: %v", ref, rerr)
176			}
177			writeErr(w, http.StatusBadGateway, "payout provider did not accept the payout")
178			return
179		}
180	
181		s.notify(Event{Type: "payout", AccountID: acct.ID, AmountCents: e.AmountCents, Reference: ref, At: e.CreatedAt})
182		writeJSON(w, http.StatusAccepted, map[string]any{
183			"entry":       toEntryJSON(e, acct.Currency),
184			"provider_id": res.ProviderID,
185			"status":      res.Status,
186		})
187	}
188	
189	// notify sends ev to the webhook, waiting at most opts.NotifyWait.
190	func (s *Server) notify(ev Event) {
191		if err := s.notifier.NotifyWithin(ev, s.opts.NotifyWait); err != nil {
192			log.Printf("notify %s for account %d: %v", ev.Type, ev.AccountID, err)
193		}
194	}
195	
196	var errTimeout = errors.New("timed out")
197	
198	// waitOrTimeout returns the result from done, or errTimeout if it takes
199	// longer than d.
200	func waitOrTimeout(done <-chan error, d time.Duration) error {
201		t := time.NewTimer(d)
202		defer t.Stop()
203		select {
204		case err := <-done:
205			return err
206		case <-t.C:
207			return errTimeout
208		}
209	}
210	
211	// pathID parses the {id} path segment.
212	func pathID(r *http.Request) (int64, error) {
213		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
214		if err != nil || id <= 0 {
215			return 0, errors.New("invalid id in path")
216		}
217		return id, nil
218	}
219	
220	// decodeJSON reads a small JSON body into dst and rejects unknown fields.
221	func decodeJSON(r *http.Request, dst any) error {
222		dec := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<16))
223		dec.DisallowUnknownFields()
224		if err := dec.Decode(dst); err != nil {
225			return fmt.Errorf("invalid request body: %w", err)
226		}
227		return nil
228	}
229	
230	func writeJSON(w http.ResponseWriter, status int, v any) {
231		w.Header().Set("Content-Type", "application/json")
232		w.WriteHeader(status)
233		if err := json.NewEncoder(w).Encode(v); err != nil {
234			log.Printf("write response: %v", err)
235		}
236	}
237	
238	// writeCreated answers 201 with v and the location of the new resource.
239	func writeCreated(w http.ResponseWriter, location string, v any) {
240		writeJSON(w, http.StatusCreated, v)
241		w.Header().Set("Location", location)
242	}
243	
244	func writeErr(w http.ResponseWriter, status int, msg string) {
245		writeJSON(w, status, map[string]string{"error": msg})
246	}
247	
248	// writeStoreError maps an error from the store (or a check built on it) to
249	// an HTTP response. Unexpected errors are logged with op and reported as 500.
250	func writeStoreError(w http.ResponseWriter, op string, err error) {
251		switch {
252		case errors.Is(err, ErrNotFound):
253			writeErr(w, http.StatusNotFound, "not found")
254		case errors.Is(err, ErrInsufficientFunds):
255			writeErr(w, http.StatusConflict, "insufficient funds")
256		case errors.Is(err, ErrDailyLimit):
257			writeErr(w, http.StatusUnprocessableEntity, "daily transfer limit reached")
258		default:
259			log.Printf("%s: %v", op, err)
260			writeErr(w, http.StatusInternalServerError, "internal error")
261		}
262	}
