1	package main
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"time"
11	)
12	
13	// Event is posted to the configured webhook when money moves.
14	type Event struct {
15		Type        string    `json:"type"`
16		AccountID   int64     `json:"account_id"`
17		AmountCents int64     `json:"amount_cents"`
18		Reference   string    `json:"reference,omitempty"`
19		At          time.Time `json:"at"`
20	}
21	
22	// Notifier delivers events to a webhook endpoint.
23	type Notifier struct {
24		url    string
25		client *http.Client
26	}
27	
28	func NewNotifier(url string, timeout time.Duration) *Notifier {
29		return &Notifier{url: url, client: &http.Client{Timeout: timeout}}
30	}
31	
32	// NotifyWithin delivers ev but stops waiting for the webhook after wait, so a
33	// slow endpoint cannot hold up an API response.
34	func (n *Notifier) NotifyWithin(ev Event, wait time.Duration) error {
35		if n.url == "" {
36			return nil
37		}
38		done := make(chan error)
39		go func() {
40			// Not tied to the request context: the request may finish first.
41			done <- n.Notify(context.Background(), ev)
42		}()
43		return waitOrTimeout(done, wait)
44	}
45	
46	// Notify posts ev to the webhook. It is a no-op when no URL is configured.
47	func (n *Notifier) Notify(ctx context.Context, ev Event) error {
48		if n.url == "" {
49			return nil
50		}
51		body, err := json.Marshal(ev)
52		if err != nil {
53			return err
54		}
55		req, err := http.NewRequestWithContext(ctx, http.MethodPost, n.url, bytes.NewReader(body))
56		if err != nil {
57			return err
58		}
59		req.Header.Set("Content-Type", "application/json")
60	
61		resp, err := n.client.Do(req)
62		if err != nil {
63			return err
64		}
65		defer resp.Body.Close()
66		_, _ = io.Copy(io.Discard, resp.Body)
67	
68		if resp.StatusCode >= 300 {
69			return fmt.Errorf("webhook: unexpected status %d", resp.StatusCode)
70		}
71		return nil
72	}
