156	func (s *Store) Withdraw(ctx context.Context, accountID, amountCents int64, reference string) (Entry, error) {
157		tx, err := s.db.BeginTx(ctx, nil)
158		if err != nil {
159			return Entry{}, err
160		}
161		defer tx.Rollback()
162	
163		if err := adjustBalance(ctx, tx, accountID, -amountCents); err != nil {
164			return Entry{}, fmt.Errorf("debit account %d: %w", accountID, err)
165		}
166		e, err := insertEntry(ctx, tx, Entry{
167			AccountID:   accountID,
168			AmountCents: -amountCents,
169			Kind:        "payout",
170			Reference:   reference,
171		})
172		if err != nil {
173			return Entry{}, err
174		}
175		return e, tx.Commit()
176	}
