178	// CreateTransfer records a transfer, moves the money and writes one ledger
179	// entry on each side, all in one transaction.
180	func (s *Store) CreateTransfer(ctx context.Context, t Transfer) (Transfer, error) {
181		tx, err := s.db.BeginTx(ctx, nil)
182		if err != nil {
183			return Transfer{}, fmt.Errorf("begin transfer: %w", err)
184		}
185		defer func() {
186			if err != nil {
187				_ = tx.Rollback()
188				return
189			}
190			err = tx.Commit()
191		}()
192	
193		t.CreatedAt = time.Now().UTC()
194		res, err := tx.ExecContext(ctx,
195			`INSERT INTO transfers (from_account_id, to_account_id, amount_cents, memo, created_at)
196			 VALUES (?, ?, ?, ?, ?)`,
197			t.FromAccountID, t.ToAccountID, t.AmountCents, t.Memo, t.CreatedAt)
198		if err != nil {
199			return Transfer{}, fmt.Errorf("insert transfer: %w", err)
200		}
201		if t.ID, err = res.LastInsertId(); err != nil {
202			return Transfer{}, err
203		}
204	
205		if err := adjustBalance(ctx, tx, t.FromAccountID, -t.AmountCents); err != nil {
206			return Transfer{}, fmt.Errorf("debit account %d: %w", t.FromAccountID, err)
207		}
208		if err := adjustBalance(ctx, tx, t.ToAccountID, t.AmountCents); err != nil {
209			return Transfer{}, fmt.Errorf("credit account %d: %w", t.ToAccountID, err)
210		}
211	
212		ref := transferReference(t.ID)
213		for _, e := range []Entry{
214			{AccountID: t.FromAccountID, AmountCents: -t.AmountCents, Kind: "transfer_out", Reference: ref},
215			{AccountID: t.ToAccountID, AmountCents: t.AmountCents, Kind: "transfer_in", Reference: ref},
216		} {
217			if _, err := insertEntry(ctx, tx, e); err != nil {
218				return Transfer{}, err
219			}
220		}
221		return t, nil
222	}
