224	func (s *Store) GetTransfer(ctx context.Context, id int64) (Transfer, error) {
225		var t Transfer
226		err := s.db.QueryRowContext(ctx,
227			`SELECT id, from_account_id, to_account_id, amount_cents, memo, created_at FROM transfers WHERE id = ?`, id).
228			Scan(&t.ID, &t.FromAccountID, &t.ToAccountID, &t.AmountCents, &t.Memo, &t.CreatedAt)
229		if errors.Is(err, sql.ErrNoRows) {
230			return Transfer{}, ErrNotFound
231		}
232		if err != nil {
233			return Transfer{}, fmt.Errorf("get transfer %d: %w", id, err)
234		}
235		return t, nil
236	}
237	
238	// adjustBalance adds delta (which may be negative) to an account's balance.
239	func adjustBalance(ctx context.Context, tx *sql.Tx, accountID, delta int64) error {
240		res, err := tx.ExecContext(ctx,
241			`UPDATE accounts SET balance_cents = balance_cents + ? WHERE id = ?`, delta, accountID)
242		if err != nil {
243			return err
244		}
245		n, err := res.RowsAffected()
246		if err != nil {
247			return err
248		}
249		if n == 0 {
250			return ErrNotFound
251		}
252		return nil
253	}
254	
255	func insertEntry(ctx context.Context, tx *sql.Tx, e Entry) (Entry, error) {
256		e.CreatedAt = time.Now().UTC()
257		res, err := tx.ExecContext(ctx,
258			`INSERT INTO entries (account_id, amount_cents, kind, reference, created_at) VALUES (?, ?, ?, ?, ?)`,
259			e.AccountID, e.AmountCents, e.Kind, e.Reference, e.CreatedAt)
260		if err != nil {
261			return Entry{}, fmt.Errorf("insert entry: %w", err)
262		}
263		if e.ID, err = res.LastInsertId(); err != nil {
264			return Entry{}, err
265		}
266		return e, nil
267	}
